"""Readable projection of sealed cumulative P2 count scores."""
import argparse
import json
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from nfl_v2.shared_subgroups import sha,write
from tools.numerical_championship import csvwrite


def main(a):
    rows=json.loads((a.output/'PRIMARY_P2_SIDE_TABLE.json').read_bytes());scores=json.loads((a.output/'SCORES.json').read_bytes());maxima=[]
    for target in sorted({r['target'] for r in scores}):
        for side in('over','under','Combined'):
            rr=[r for r in scores if r['target']==target and r['side']==side and r['selection_metrics']['hit_rate'] is not None]
            best=max(r['selection_metrics']['hit_rate'] for r in rr)
            maxima.extend(dict(target=target,side=side,procedure_id=r['procedure_id'],history_regime=r['history_regime'],product_id=r['product_id'],wins=r['selection_metrics']['WIN'],losses=r['selection_metrics']['LOSS'],decided=r['n'],selected=r['forecast_rows'],hit_rate=best,coverage=r['selection_metrics']['selection_coverage'],source_record_id=r['record_id'],interpretation='Raw own-pool maximum; no support veto; D1/D2 prior-only subsets are not full-law learner comparisons.') for r in rr if abs(r['selection_metrics']['hit_rate']-best)<=1e-12)
    write(a.output/'RAW_P2_SIDE_MAXIMA.json',maxima);csvwrite(a.output/'RAW_P2_SIDE_MAXIMA.csv',maxima)
    lines=['# Three-week primary P2 selected-side counts','','The cumulative P2 reporting gap is closed for **138 supported exact law/procedure/history products**: 414 Over, Under and Combined score views across Weeks 5–7. Each count is summed from unchanged canonical weekly scores and independently reconciled to the retained selected side and statistical state. No decisions, probabilities or grades were regenerated.','','The following continuity example is the unchanged C02 H-MULTI complete leaf law under P2. The full machine table includes every law, history and strict-current alternative; this example is not a hindsight winner or a release recommendation.','','| Category | Predicted Over wins/decided | Over hit rate | Predicted Under wins/decided | Under hit rate | Combined wins/decided | Combined hit rate | Selected / outer offers |','|---|---:|---:|---:|---:|---:|---:|---:|']
    pct=lambda v:'N/A' if v is None else f'{100*v:.2f}%'
    for r in rows:
        if not('c02' in r['procedure_id'] and 'strict' not in r['procedure_id'] and r['history_regime']=='H-MULTI'):continue
        lines.append(f"| {r['target']} | {r['Over_wins']}/{r['Over_decided']} | {pct(r['Over_hit_rate'])} | {r['Under_wins']}/{r['Under_decided']} | {pct(r['Under_hit_rate'])} | {r['Combined_wins']}/{r['Combined_decided']} | {pct(r['Combined_hit_rate'])} | {r['Combined_selected']}/{r['outer_eligible_opportunities']} |")
    lines += ['', 'For passing attempts, five of six selected Overs won, while 40 of 74 selected Unders won. The combined result is45/80=56.25%; averaging83.33% and54.05% would be wrong. The six-Over pool is small. Passing-yard performance is adverse:13/29Over plus16/51Under yields29/80=36.25%. All losses remain visible.', '', 'Complete Leaf/C02 products replace only their matching partial parent P2 products. GLM and valid D1/D2 saved prior-law subsets remain separate. A D1/D2 subset with a tiny denominator is not a full-population probability winner. [Raw side maxima](RAW_P2_SIDE_MAXIMA.csv) retain exact support and coverage without a posthoc minimum-support filter.', '', 'The source panel covers42/43 games across the stated three weeks, with the missing W5 Thursday game excluded. Full category opportunity denominators include every retained offer, including unavailable law-week cells. Selection coverage, admitted-law abstentions, unknown participation, missing actuals, pushes, voids and unresolved records remain separate. A zero decided denominator has N/A hit rate. Combined counts equal Over plus Under for every state and selected count.', '', 'Selected-side fallback counts use the exact retained law origin. The admitted-pool fallback count is separately named and is not substituted for a selected-side count. For base/C02, recovered saved leaf IDs/histograms identify learned laws; the explicit reused-prior marker identifies fallback. Other parametric products use their original fallback field. No roster, role or difficult-participant filtering was added.', '', 'The existing500 whole-game sensitivity bootstrap(seed1703) uses the saved WIN/LOSS states and requires at least eight game clusters. Three weeks remain insufficient for the registered week-based interval. Intervals are descriptive and unadjusted for selection/multiplicity. Unique games, players and player-games are computed from saved identities; repeated snapshots are not counted as independent picks.', '', 'This closure evaluates selected-side hit counts. Cumulative all-law Brier/log loss remains in the [separate proper-score product](../w5-w7-cumulative-v1/README.md), whose mask must not be substituted for a selected-side proper-score mask. Weekly selected-side/cohort/K probability annotations remain preserved. Existing weekly top-K/cohort strategies are unchanged and are not newly pooled here.', '', 'Every selected bookmaker contract remains unresolved. Statistical wins do not establish sportsbook settlement or profitability; prices, EV, ROI and CLV remain unavailable. The forecasts remain retrospective known-target-time reconstructions, not original issuance or a deployed policy. No production change, fit, inference, probability recalculation or new NFL observation occurred.', '', '[Every P2 law with Over/Under/Combined counts](PRIMARY_P2_SIDE_TABLE.csv) · [Canonical scores](SCORES.json) · [Frozen source/code roster](FROZEN_PROTOCOL.json) · [Execution receipt](RUN_RECEIPT.json).']
    (a.output/'README.md').write_text('\n'.join(lines)+'\n')
    write(a.output/'ROOT_ADDITION_HANDOFF.json',dict(state='ONE_SEALED_ADDITIONAL_CANONICAL_SOURCE',source_artifact=(a.output/'SCORES.json').relative_to(a.root).as_posix(),source_sha256=sha(a.output/'SCORES.json'),rows=len(scores),law_history_products=len(rows),raw_maximum_rows=len(maxima),report_code_sha256=sha(__file__),prior_27_canonical_sources_changed=False,metadata_annotations_required=False,new_fits=0,new_inference=0,new_probabilities=0,new_grades=0))


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output=a.output.resolve();main(a)
